"use client"

/**
 * Verification Code (Notchset) v1.0.0 · Notchset
 * Docs: https://notchset.dev/components/otp-input
 * MIT licensed: free to use, change and share.
 */

import * as React from "react"

import { cn } from "@/lib/utils"
import { NumberFlow } from "@/lib/notchset/number-flow"
import { Announcer, DrawCheck, useComposedRefs, useTimeline } from "@/lib/notchset/shared"
import { useSound } from "@/lib/notchset/sound"
import { useVerificationCode } from "@/lib/notchset/verification-code"

/*
 * Verification Code: one real input under six boxes. Each digit pops in with a note that climbs as the
 * code fills; a pasted code fills one box at a time. While your onVerify runs the boxes ripple; a good
 * code folds them into one check, a wrong one shakes them red and clears. A resend countdown sits below.
 */


interface OtpInputProps extends Omit<React.ComponentPropsWithoutRef<"input">, "value" | "defaultValue" | "onChange" | "maxLength" | "size"> {
  /** Checks a full code. Resolve true (or nothing) when it's right; false or a rejection when it's wrong. */
  onVerify: (code: string) => Promise<boolean | void> | boolean | void
  /** Asks for a new code; the countdown restarts. */
  onResend?: (() => unknown) | undefined
  /** Seconds before Resend is offered. Default 24; 0 hides the countdown. */
  resendAfter?: number | undefined
  /** The input's accessible name. Default "Verification code". */
  label?: string | undefined
  /** Number of digits. Default 6. */
  length?: number | undefined
  sound?: boolean | undefined
}

const OtpInput = React.forwardRef<HTMLInputElement, OtpInputProps>(function OtpInput(
  { onVerify, onResend, resendAfter = 24, label = "Verification code", length = 6, sound = true, className, disabled, ...props },
  ref
) {
  const { sfx } = useSound(sound)
  const timeline = useTimeline()
  const size = Math.max(4, Math.min(8, Math.floor(length)))
  const [focused, setFocused] = React.useState(false)
  const inner = React.useRef<HTMLInputElement>(null)
  const refs = useComposedRefs(inner, ref)
  const { code, type, status: state, shakes, left, submit: verify, restart } = useVerificationCode({
    verify: onVerify,
    resendAfter,
    input: inner,
    onStatusChange: (s) => {
      if (s === "verified") timeline.after(300, () => sfx.chime())
      else if (s === "wrong") sfx.buzz()
    },
  })

  const set = (next: string) => {
    if (next.length > code.length) sfx.tone(500 + next.length * 80, 0.05, "triangle", 0.045)
    else if (next.length < code.length) sfx.del()
    type(next)
    if (next.length === size) void verify(next)
  }

  const locked = state !== "idle" || disabled
  const active = Math.min(code.length, size - 1)
  const verified = state === "verified"
  return (
    <div data-slot="otp-input" data-notchset="" className={cn("flex flex-col items-center gap-4", className)}>
      <div className="relative">
        <input
          ref={refs}
          value={code}
          inputMode="numeric"
          autoComplete="one-time-code"
          pattern="[0-9]*"
          maxLength={size}
          aria-label={label}
          aria-invalid={state === "wrong" || undefined}
          disabled={disabled}
          readOnly={locked}
          onFocus={() => {
            setFocused(true)
            sfx.focus()
          }}
          onBlur={() => setFocused(false)}
          onChange={(event) => {
            if (locked) return
            set(event.target.value.replace(/\D/g, "").slice(0, size))
          }}
          onPaste={(event) => {
            event.preventDefault()
            if (locked) return
            const digits = event.clipboardData.getData("text").replace(/\D/g, "").slice(0, size)
            if (!digits) return
            type("")
            Array.from(digits).forEach((_, i) =>
              timeline.after(i * 60, () => {
                sfx.tone(500 + (i + 1) * 80, 0.05, "triangle", 0.045)
                type(digits.slice(0, i + 1))
                if (i + 1 === size) void verify(digits)
              })
            )
          }}
          className="absolute inset-0 z-[2] size-full cursor-text border-0 p-0 text-[16px] opacity-0 [caret-color:transparent]"
          {...props}
        />
        <div aria-hidden="true" className={cn("flex items-center gap-2", shakes > 0 && (shakes % 2 ? "animate-[ns-shake_.42s]" : "animate-[ns-shake-b_.42s]"))}>
          {Array.from({ length: size }, (_, i) => {
            const digit = code[i]
            const isActive = focused && state === "idle" && i === active && !digit
            const half = (size - 1) / 2
            return (
              <React.Fragment key={i}>
                <span
                  className={cn(
                    "relative grid h-[54px] w-11 place-items-center rounded-[min(var(--radius),12px)] border bg-[var(--background)] font-mono text-[22px] font-medium text-[var(--foreground)] [transition:border-color_.2s,box-shadow_.25s,transform_.5s_cubic-bezier(.5,0,.2,1),scale_.5s_cubic-bezier(.5,0,.2,1),translate_.5s_cubic-bezier(.5,0,.2,1),rotate_.5s_cubic-bezier(.5,0,.2,1),opacity_var(--ns-time-state)] max-[380px]:h-12 max-[380px]:w-9",
                    state === "wrong" && "border-[var(--destructive)]",
                    state !== "wrong" && (isActive || state === "checking") && "border-[color-mix(in_oklab,var(--foreground)_55%,var(--input))] shadow-[0_0_0_4px_color-mix(in_oklab,var(--foreground)_7%,transparent)]",
                    state !== "wrong" && !isActive && state !== "checking" && digit && "border-[color-mix(in_oklab,var(--foreground)_28%,var(--input))]",
                    state !== "wrong" && !isActive && state !== "checking" && !digit && "border-[var(--input)]",
                    state === "checking" && "animate-[ns-wave_.7s_ease-in-out_infinite]",
                    verified && "scale-60 opacity-0"
                  )}
                  style={{
                    animationDelay: state === "checking" ? `${i * 70}ms` : undefined,
                    transitionDelay: verified ? `${i * 30}ms` : undefined,
                    translate: verified ? `${(half - i) * 52}px 0` : undefined,
                  }}
                >
                  {digit && <span className="animate-[ns-digit_.35s_var(--ns-ease-pop)_both]">{digit}</span>}
                  {isActive && <span className="block h-[22px] w-[1.5px] animate-[ns-blink_1s_steps(1)_infinite] bg-[var(--foreground)]" />}
                </span>
                {i === Math.floor(size / 2) - 1 && <span className={cn("block h-[1.5px] w-2 rounded-[1px] bg-[var(--muted-foreground)] [transition:opacity_var(--ns-time-state)]", verified ? "opacity-0" : "opacity-100")} />}
              </React.Fragment>
            )
          })}
        </div>
        <div
          aria-hidden="true"
          className={cn("pointer-events-none absolute inset-0 flex items-center justify-center gap-2.5 text-[15px] font-medium text-[var(--foreground)] [transition:opacity_.3s_.3s,transform_.55s_var(--ns-ease-pop)_.3s,scale_.55s_var(--ns-ease-pop)_.3s,translate_.55s_var(--ns-ease-pop)_.3s,rotate_.55s_var(--ns-ease-pop)_.3s]", verified ? "scale-100 opacity-100" : "scale-[.8] opacity-0")}
        >
          <span className="grid size-[30px] place-items-center rounded-full bg-[var(--primary)] text-[var(--primary-foreground)]">
            <DrawCheck shown={verified} className="size-[15px]" />
          </span>
          Verified
        </div>
      </div>
      {resendAfter > 0 && onResend && (
        <div className="flex items-center gap-2 text-[length:var(--ns-type-note)] text-[var(--muted-foreground)]">
          {left > 0 ? (
            <span className="inline-flex items-center gap-1 font-mono">Resend in <NumberFlow value={`0:${String(left).padStart(2, "0")}`} /></span>
          ) : (
            <button
              type="button"
              onClick={() => {
                sfx.tick()
                restart()
                onResend()
              }}
              className="animate-[ns-fade-up_.3s_both] cursor-pointer rounded-sm text-[length:var(--ns-type-note)] font-medium text-[var(--foreground)] underline underline-offset-[3px] outline-none focus-visible:ring-[length:var(--ns-focus-width,2px)] focus-visible:ring-[color:var(--ns-focus-color,var(--ring))] focus-visible:ring-offset-2 focus-visible:ring-offset-[var(--background)]"
            >
              Resend code
            </button>
          )}
        </div>
      )}
      <Announcer message={state === "checking" ? "Checking code" : verified ? "Verified" : state === "wrong" ? "That code is not right" : ""} />
    </div>
  )
})

export { OtpInput, type OtpInputProps }

"use client"

import * as React from "react"

import { cn } from "@/lib/utils"

/*
 * NumberFlow: the fluid number every changing figure renders through (countdowns, times, counts, totals).
 * Each digit is its own 0–9 column that springs to the new digit with a slight motion blur; digits that
 * appear or disappear animate their width, so the text never jumps. Other characters (":", ",", " ")
 * swap in place. Screen readers get the plain value.
 */

const H = 1.15 // em, one digit row

function Digit({ d, enter, tight }: { d: number; enter: boolean; tight?: boolean | undefined }) {
  // Each change flips between two identical blur keyframes, so the blur restarts every time.
  const [seen, setSeen] = React.useState(d)
  const [flips, setFlips] = React.useState(0)
  if (seen !== d) {
    setSeen(d)
    setFlips((n) => n + 1)
  }
  return (
    <span
      aria-hidden="true"
      className={cn(
        "relative inline-block [clip-path:inset(0_-0.15em)]",
        // Tight digits are narrower than their glyphs: they clip only up and down (the clip-path bounds the sides), so a 1 isn't cut.
        tight ? "[overflow-x:visible] [overflow-y:clip] transition-[width] duration-[.55s] ease-[var(--ns-ease-settle)] motion-reduce:transition-none" : "w-[1ch] overflow-hidden",
        enter && "animate-[ns-num-in_.55s_var(--ns-ease-settle)_both] motion-reduce:animate-none"
      )}
      // Tight digits: a 1 is narrower than the rest, as in a headline price.
      style={{ height: `${H}em`, lineHeight: `${H}em`, width: tight ? (d === 1 ? "0.43em" : "0.58em") : undefined }}
    >
      <span
        className={cn(
          "flex flex-col",
          // Tight: each glyph keeps a box as wide as itself, centred in the narrower slot.
          tight && "items-center",
          "[transition:transform_.85s_var(--ns-ease-settle),scale_.85s_var(--ns-ease-settle),translate_.85s_var(--ns-ease-settle),rotate_.85s_var(--ns-ease-settle)] motion-reduce:transition-none",
          flips > 0 && (flips % 2 ? "animate-[ns-num-blur_.45s_ease-out]" : "animate-[ns-num-blur-b_.45s_ease-out]")
        )}
        style={{ transform: `translateY(${-d * H}em)` }}
      >
        {Array.from({ length: 10 }, (_, i) => (
          <span key={i} className={cn("block text-center", tight && "w-[0.76em] shrink-0")} style={{ height: `${H}em` }}>
            {i}
          </span>
        ))}
      </span>
    </span>
  )
}

interface NumberFlowProps extends Omit<React.ComponentPropsWithoutRef<"span">, "children"> {
  /** The value as it should read, e.g. 42, "09:30" or "1,204". */
  value: string | number
  /** Proportional digit widths (a 1 is 0.43em, the rest 0.58em), for large headline figures. */
  tight?: boolean | undefined
}

const NumberFlow = React.forwardRef<HTMLSpanElement, NumberFlowProps>(function NumberFlow({ value, tight, className, ...props }, ref) {
  const text = String(value)
  const chars = Array.from(text)
  // Positions are counted from the right, so the ones digit stays the ones digit when the length changes.
  const [initialLength] = React.useState(chars.length)
  const [prev, setPrev] = React.useState(text)
  const [leaving, setLeaving] = React.useState<{ id: string; ch: string }[]>([])
  if (prev !== text) {
    const old = Array.from(prev)
    if (old.length > chars.length) {
      const gone = old.slice(0, old.length - chars.length).filter((ch) => ch >= "0" && ch <= "9")
      setLeaving((l) => [...l, ...gone.map((ch, i) => ({ id: `${prev}>${text}:${i}`, ch }))].slice(-4))
    }
    setPrev(text)
  }

  return (
    <span ref={ref} data-slot="number-flow" className={cn("inline-flex whitespace-nowrap tabular-nums", className)} {...props}>
      <span className="sr-only">{text}</span>
      {leaving.map((g) => (
        <span
          key={`out-${g.id}`}
          aria-hidden="true"
          className="inline-block w-0 animate-[ns-num-out_.45s_var(--ns-ease-settle)_both] overflow-hidden text-center"
          style={{ height: `${H}em`, lineHeight: `${H}em` }}
          onAnimationEnd={() => setLeaving((l) => l.filter((x) => x.id !== g.id))}
        >
          {g.ch}
        </span>
      ))}
      {chars.map((ch, i) => {
        const pos = chars.length - i
        return ch >= "0" && ch <= "9" ? (
          <Digit key={`d${pos}`} d={Number(ch)} enter={pos > initialLength} tight={tight} />
        ) : (
          <span key={`s${pos}`} aria-hidden="true" className="inline-block whitespace-pre" style={{ height: `${H}em`, lineHeight: `${H}em` }}>
            {ch}
          </span>
        )
      })}
    </span>
  )
})

export { NumberFlow, type NumberFlowProps }

"use client"

import * as React from "react"

/*
 * The controller every verification-code input shares: the typed code, the check and its outcome, the
 * wrong-code reset and the resend countdown. Renderers (boxes, underlines, big numerals) own their look
 * and their sounds and call `submit` when the code is complete.
 *
 * - A check's result only lands if no newer check started (a slow server can't overwrite a newer code).
 * - A rejected or thrown check is a wrong code. `false` or a failed Response is wrong; anything else is right.
 * - Typing again cancels a pending clear (the new code is never wiped), and nothing lands after unmount.
 * - A wrong code holds for `clearAfter` ms (long enough to read and shake), then clears and refocuses.
 * - The countdown runs a second at a time and stops once the code is verified.
 */

type VerificationStatus = "idle" | "checking" | "verified" | "wrong"

interface VerificationCodeOptions {
  /** Checks a complete code. Resolve false (or reject) when it's wrong. */
  verify: (code: string) => boolean | void | Response | PromiseLike<boolean | void | Response>
  /** After a right code. */
  onVerified?: ((code: string) => void) | undefined
  /** Every status change (for sounds and announcements in the renderer). */
  onStatusChange?: ((status: VerificationStatus) => void) | undefined
  /** Seconds before a new code can be asked for. 0: no countdown. */
  resendAfter: number
  /** How long a wrong code stays before it clears, ms. */
  clearAfter?: number | undefined
  /** The input to refocus after a wrong code clears. */
  input: React.RefObject<HTMLInputElement | null>
}

function useVerificationCode({ verify, onVerified, onStatusChange, resendAfter, clearAfter = 900, input }: VerificationCodeOptions) {
  const [code, setCode] = React.useState("")
  const [status, setStatusState] = React.useState<VerificationStatus>("idle")
  const [shakes, setShakes] = React.useState(0)
  const [left, setLeft] = React.useState(resendAfter)
  const run = React.useRef(0)
  const timers = React.useRef<number[]>([])
  React.useEffect(
    () => () => {
      // Unmounted: no pending check or clear may land.
      run.current++
      timers.current.forEach((t) => window.clearTimeout(t))
    },
    []
  )
  const later = React.useCallback((fn: () => void, ms: number) => {
    const id = window.setTimeout(() => {
      timers.current = timers.current.filter((t) => t !== id)
      fn()
    }, ms)
    timers.current.push(id)
  }, [])
  // A complete code is sent a beat after its last digit; any keystroke in between cancels that send.
  const queued = React.useRef(0)
  const checking = React.useRef(false)
  const setStatus = (s: VerificationStatus) => {
    setStatusState(s)
    onStatusChange?.(s)
  }

  React.useEffect(() => {
    if (left <= 0 || status === "verified") return
    const t = window.setTimeout(() => setLeft((n) => n - 1), 1000)
    return () => window.clearTimeout(t)
  }, [left, status])

  /** Checks a complete code. */
  const submit = async (full: string) => {
    // One check at a time: a second complete code waits for the first to finish.
    if (checking.current) return
    checking.current = true
    const id = ++run.current
    setStatus("checking")
    let ok = false
    try {
      const result = await verify(full)
      ok = result !== false && !(typeof Response !== "undefined" && result instanceof Response && !result.ok)
    } catch {
      ok = false
    }
    checking.current = false
    if (id !== run.current) return
    if (ok) {
      setStatus("verified")
      onVerified?.(full)
      return
    }
    setStatus("wrong")
    setShakes((n) => n + 1)
    later(() => {
      if (id !== run.current) return
      setCode("")
      setStatus("idle")
      input.current?.focus()
    }, clearAfter)
  }

  /** Starts the countdown again (after asking for a new code) and clears what was typed. */
  const restart = () => {
    run.current++
    queued.current++
    setLeft(resendAfter)
    setCode("")
    setStatus("idle")
  }

  /** A typed code; leaving the wrong state when the person starts again. */
  const type = (next: string) => {
    // A new edit owns the field: the wrong code's pending clear and any queued send no longer apply.
    queued.current++
    if (status === "wrong") run.current++
    setCode(next)
    if (status === "wrong") setStatus("idle")
  }

  /** Sends `full` after `ms`, unless the person types again first (then this send is dropped). */
  const queueSubmit = (full: string, ms: number) => {
    const ticket = ++queued.current
    later(() => {
      if (ticket === queued.current) void submit(full)
    }, ms)
  }

  return { code, type, status, shakes, left, submit, queueSubmit, restart, later, locked: status === "checking" || status === "verified" }
}

export { useVerificationCode, type VerificationCodeOptions, type VerificationStatus }

"use client"

import * as React from "react"

import { cn } from "@/lib/utils"

/*
 * The shared parts: the rolling label every state change goes through, the check that draws
 * itself, the spinner and the live dot, and a timeline that schedules a component's steps and clears
 * them when it unmounts. Every class string is a plain literal (the shadcn CLI only rewrites those for
 * apps with tailwind.prefix). Keyframes (ns-*) live in the foundation CSS.
 *
 * Easing vocabulary (the design's names): press var(--ns-ease-press) for scale on press; roll
 * var(--ns-ease-reshape) for label rolls, menus and width morphs; pop var(--ns-ease-pop) for
 * icon swaps and checks landing; draw cubic-bezier(.6,0,.2,1) for strokes and sweeps; exit
 * cubic-bezier(.6,0,.9,.5) for things leaving.
 */

/** Runs on the client before paint, and as an effect on the server (React 18 warns about layout effects there). */
const useIsomorphicLayoutEffect = typeof window !== "undefined" ? React.useLayoutEffect : React.useEffect

/** Points one ref (callback or object) at `node`. */
function assignRef<T>(ref: React.Ref<T> | undefined, node: T | null) {
  if (typeof ref === "function") ref(node)
  else if (ref) (ref as React.MutableRefObject<T | null>).current = node
}

/** Sets every ref passed (callback or object), so a component can keep its own ref and forward the caller's. */
function useComposedRefs<T>(...refs: (React.Ref<T> | undefined)[]) {
  const latest = React.useRef(refs)
  useIsomorphicLayoutEffect(() => {
    latest.current = refs
  })
  return React.useCallback((node: T | null) => {
    for (const ref of latest.current) assignRef(ref, node)
  }, [])
}

/** Schedules a component's steps; every pending step is cleared on clear() and on unmount. */
function useTimeline() {
  const timers = React.useRef<Set<ReturnType<typeof setTimeout>>>(new Set())
  React.useEffect(() => {
    const set = timers.current
    return () => {
      for (const t of set) clearTimeout(t)
      set.clear()
    }
  }, [])
  return React.useMemo(
    () => ({
      after(ms: number, fn: () => void) {
        const t = setTimeout(() => {
          timers.current.delete(t)
          fn()
        }, ms)
        timers.current.add(t)
        return t
      },
      clear() {
        for (const t of timers.current) clearTimeout(t)
        timers.current.clear()
      },
    }),
    []
  )
}

/** Resolves after `ms` (a minimum time a state shows, so a fast promise still reads). */
const wait = (ms: number) => new Promise<void>((resolve) => setTimeout(resolve, ms))

/**
 * A fixed-height window over a stack of rows; row `index` shows, the others roll past (.5s roll). Only
 * the showing row is in the accessibility tree, so the button's name is always the current label.
 */
function RollingLabel({ rows, index, size = "default", align = "center", fit = false, rowHeight, className }: { rows: readonly React.ReactNode[]; index: number; size?: "default" | "sm" | undefined; align?: "center" | "start" | undefined; /** Rows as wide as their own text (inside a window sized to the active row). */ fit?: boolean | undefined; /** A row height in px, for titles (overrides size). */ rowHeight?: number | undefined; className?: string | undefined }) {
  const height = rowHeight ?? (size === "sm" ? 18 : 20)
  return (
    <span data-slot="rolling-label" className={cn("relative block overflow-hidden", !rowHeight && (size === "sm" ? "h-[18px]" : "h-5"), className)} style={rowHeight ? { height: rowHeight } : undefined}>
      <span
        className={cn("flex flex-col transition-transform duration-500 ease-[var(--ns-ease-reshape)] motion-reduce:transition-none", fit && (align === "center" ? "items-center" : "items-start"))}
        style={{ transform: `translateY(${-index * height}px)` }}
      >
        {rows.map((row, i) => (
          <span
            key={i}
            aria-hidden={i === index ? undefined : true}
            className={cn("flex shrink-0 items-center gap-2 whitespace-nowrap", !rowHeight && (size === "sm" ? "h-[18px]" : "h-5"), align === "center" ? "justify-center" : "justify-start", fit && "w-max")}
            style={rowHeight ? { height: rowHeight, lineHeight: `${rowHeight}px` } : undefined}
          >
            {row}
          </span>
        ))}
      </span>
    </span>
  )
}

/** The check that draws itself in (.45s draw after .15s) when `shown`. */
function DrawCheck({ shown, className }: { shown: boolean; className?: string | undefined }) {
  return (
    <svg viewBox="0 0 24 24" aria-hidden="true" className={cn("size-4 shrink-0", className)} fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
      <path
        d="M20 6 9 17l-5-5"
        className="[stroke-dasharray:24] transition-[stroke-dashoffset] delay-150 duration-[450ms] ease-[cubic-bezier(.6,0,.2,1)] motion-reduce:transition-none"
        style={{ strokeDashoffset: shown ? 0 : 24 }}
      />
    </svg>
  )
}

/** The 14px spinner: an arc turning every .7s. */
function Spinner({ className }: { className?: string | undefined }) {
  return (
    <svg viewBox="0 0 24 24" aria-hidden="true" className={cn("size-3.5 shrink-0 animate-[ns-spin_.7s_linear_infinite]", className)} fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round">
      <circle cx="12" cy="12" r="9" className="[stroke-dasharray:20_40]" />
    </svg>
  )
}

/** A 7px dot with a ring that keeps blooming out of it (live). */
function LiveDot({ className }: { className?: string | undefined }) {
  return (
    <span aria-hidden="true" className={cn("relative inline-flex size-[7px] shrink-0", className)}>
      <span className="absolute inset-0 animate-[ns-live_1.2s_ease-out_infinite] rounded-full bg-current" />
      <span className="relative size-full rounded-full bg-current" />
    </span>
  )
}

/**
 * Where overlays (menus, tooltips) portal to. Unset, they portal to document.body, where your
 * :root theme applies. Set it when the theme lives on an element instead of :root:
 *   <PortalContext.Provider value={element}>…</PortalContext.Provider>
 */
const PortalContext = React.createContext<HTMLElement | null>(null)

/** The container for an overlay's Portal: the provided element, else undefined (document.body). */
function usePortal() {
  return React.useContext(PortalContext) ?? undefined
}

/**
 * Writes text to the clipboard and resolves true only when it landed (falls back to a hidden textarea
 * where the async API is missing or blocked). Show "Copied" only on true.
 */
async function copyText(text: string): Promise<boolean> {
